import React, { useState } from 'react';
import { MapPin, ChevronRight, ChevronLeft, Search, Box, Globe, Layers, Zap } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); // ZONES -> AREAS -> BINS
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- COMPREHENSIVE DATA MODEL ---
  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA', 
      theme: '#FF5B03', bg: '#FFB6A9', // Sungold + Petal Pink
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge Path', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus Gate', code: 'URD-12', bins: ['BN-502', 'BN-503', 'BN-508', 'BN-510'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO', 
      theme: '#47510B', bg: '#CAD23C', // Grassy + Seed Green
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown Hub', code: 'MSQ-01', bins: ['BN-101', 'BN-102', 'BN-103'] },
        { id: 'A-4', name: 'City Plaza', location: 'Commercial Wing', code: 'CPZ-99', bins: ['BN-201', 'BN-202'] }
      ]
    },
    {
      id: 'Z-3', name: 'SOUTH_PORT', code: 'SP-CHARLIE', 
      theme: '#AB1717', bg: '#A1AED1', // Beet Red + Blue Linen
      areas: [
        { id: 'A-5', name: 'Dockside Terminal', location: 'Wharf 7', code: 'W7-DK', bins: ['BN-881', 'BN-889'] }
      ]
    }
  ];

  // --- FILTERING LOGIC ---
  const filteredData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()) || z.code.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full h-full flex flex-col gap-8 p-4 md:p-8 animate-slot bg-[#FDFAD8]/30 rounded-[50px]">

      {/* 🚀 SMOOTH HEADER SYSTEM */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-6 w-full md:w-auto">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} 
              className="w-14 h-14 flex items-center justify-center bg-[#AB1717] text-white rounded-full hover:scale-110 active:scale-95 transition-all shadow-[0_8px_20px_rgba(171,23,23,0.3)]"
            >
              <ChevronLeft size={28} strokeWidth={3} />
            </button>
          )}
          <div className="flex flex-col">
            <h2 className="text-4xl md:text-5xl font-[1000] text-[#47510B] tracking-tighter uppercase italic leading-none">
              {viewLevel === 'ZONES' ? 'SECTORS' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
            </h2>
            <div className="flex items-center gap-2 mt-2">
              <div className="h-2 w-12 rounded-full bg-[#FF5B03]" />
              <span className="text-[10px] font-black text-[#A1AED1] uppercase tracking-[0.3em]">
                {viewLevel === 'ZONES' ? 'GLOBAL_VIEW' : `PATH: ${selectedZone?.code}`}
              </span>
            </div>
          </div>
        </div>

        {/* ELASTIC SEARCH BAR */}
        <div className="relative w-full md:w-96 group">
          <Search className="absolute left-5 top-4 text-[#AB1717] group-focus-within:rotate-90 transition-transform" size={20} />
          <input 
            type="text" 
            placeholder="TYPE_TO_FILTER..." 
            className="w-full bg-white/80 border-none rounded-[35px] py-4 pl-14 pr-8 text-sm font-black text-[#47510B] shadow-[0_10px_30px_rgba(0,0,0,0.05)] focus:ring-4 focus:ring-[#CAD23C]/50 transition-all outline-none"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* 🌊 MAIN LIQUID CONTENT AREA */}
      <div className="flex-grow overflow-y-auto custom-scrollbar pr-2">

        {/* LEVEL 1: ZONES (Soft Floating Orbs) */}
        {viewLevel === 'ZONES' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 py-4">
            {filteredData.map(zone => (
              <div 
                key={zone.id} 
                onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
                style={{ backgroundColor: zone.bg }}
                className="group relative p-10 rounded-[70px] cursor-pointer hover:-translate-y-4 transition-all duration-500 shadow-2xl border-b-[15px] border-black/10 overflow-hidden"
              >
                <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/10 rounded-full blur-3xl group-hover:bg-white/30 transition-all" />
                <div className="flex justify-between items-start mb-12">
                  <div className="bg-white p-5 rounded-[30px] shadow-lg">
                    <Globe size={36} style={{ color: zone.theme }} className="group-hover:rotate-12 transition-transform" />
                  </div>
                  <span className="bg-[#47510B] text-[#FFF24D] text-[10px] font-black px-5 py-2 rounded-full shadow-md uppercase tracking-widest">
                    {zone.code}
                  </span>
                </div>
                <h3 className="text-4xl font-[1000] text-[#47510B] tracking-tighter leading-none mb-4 uppercase italic">
                  {zone.name}
                </h3>
                <div className="flex items-center gap-2">
                  <Zap size={14} className="text-[#FF5B03]" />
                  <p className="text-xs font-black text-[#47510B]/60 uppercase tracking-widest">
                    {zone.areas.length} ACTIVE_NODES
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 2: AREAS (Fluid Tracks) */}
        {viewLevel === 'AREAS' && (
          <div className="flex flex-col gap-6 max-w-6xl mx-auto py-4">
            {filteredData.map(area => (
              <div 
                key={area.id} 
                onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
                className="group flex flex-col md:flex-row items-center bg-white/70 backdrop-blur-sm p-6 rounded-[50px] hover:bg-[#FFF24D] transition-all cursor-pointer border-4 border-transparent hover:border-[#47510B] shadow-[0_15px_35px_rgba(0,0,0,0.03)]"
              >
                <div className="w-20 h-20 rounded-[30px] bg-[#A1AED1]/30 flex items-center justify-center text-[#AB1717] group-hover:bg-[#AB1717] group-hover:text-white transition-all shadow-inner">
                  <MapPin size={32} strokeWidth={3} />
                </div>
                <div className="md:ml-10 flex-grow text-center md:text-left mt-6 md:mt-0">
                  <h4 className="text-3xl font-black text-[#47510B] uppercase tracking-tighter italic leading-none mb-2">
                    {area.name}
                  </h4>
                  <div className="flex flex-wrap justify-center md:justify-start gap-3">
                    <span className="text-[10px] font-black text-white bg-[#A1AED1] px-3 py-1 rounded-full uppercase">
                      LOC: {area.location}
                    </span>
                    <span className="text-[10px] font-black text-[#AB1717] border-2 border-[#AB1717] px-3 py-1 rounded-full uppercase">
                      CODE: {area.code}
                    </span>
                  </div>
                </div>
                <div className="mt-6 md:mt-0 px-10 py-4 bg-[#CAD23C] rounded-[30px] text-xl font-black text-[#47510B] group-hover:bg-[#47510B] group-hover:text-[#CAD23C] transition-all shadow-md">
                  {area.bins.length} UNITS
                </div>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 3: BINS (Vibrant Glowing Spheres) */}
        {viewLevel === 'BINS' && (
          <div className="flex flex-wrap justify-center gap-10 py-12">
            {selectedArea.bins.map(binId => (
              <div 
                key={binId} 
                className="w-36 h-36 md:w-48 md:h-48 bg-[#47510B] rounded-[60px] flex flex-col items-center justify-center gap-4 relative group hover:scale-110 hover:shadow-[0_20px_50px_rgba(255,91,3,0.4)] transition-all duration-500 cursor-help"
              >
                <div className="absolute -top-3 -right-3 w-14 h-14 bg-[#FF5B03] rounded-full flex items-center justify-center border-4 border-[#FDFAD8] text-white shadow-lg group-hover:rotate-12 transition-transform">
                  <Box size={24} />
                </div>
                <span className="text-[#CAD23C] font-[1000] text-2xl tracking-tighter italic">
                  {binId}
                </span>
                <div className="px-3 py-1 bg-white/10 rounded-full text-[8px] font-black text-[#A1AED1] uppercase tracking-[0.2em]">
                  Live_Link_OK
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 🧭 NAVIGATION FOOTER: EASE-OF-USE INDICATOR */}
      <div className="flex justify-center mt-auto">
        <div className="flex gap-6 p-3 bg-white/50 backdrop-blur-xl rounded-full border-2 border-white shadow-2xl">
          <button onClick={() => setViewLevel('ZONES')} className={`w-4 h-4 rounded-full transition-all ${viewLevel === 'ZONES' ? 'bg-[#FF5B03] scale-150 shadow-[0_0_15px_#FF5B03]' : 'bg-[#47510B]/20'}`} />
          <button onClick={() => selectedZone && setViewLevel('AREAS')} className={`w-4 h-4 rounded-full transition-all ${viewLevel === 'AREAS' ? 'bg-[#CAD23C] scale-150 shadow-[0_0_15px_#CAD23C]' : 'bg-[#47510B]/20'}`} />
          <button onClick={() => selectedArea && setViewLevel('BINS')} className={`w-4 h-4 rounded-full transition-all ${viewLevel === 'BINS' ? 'bg-[#AB1717] scale-150 shadow-[0_0_15px_#AB1717]' : 'bg-[#47510B]/20'}`} />
        </div>
      </div>

    </div>
  );
};

export default AreasZonesTab;
